<template>
  <el-dialog
    width="900px"
    append-to-body
    v-dialog-out
    :title="title"
    :visible="dialogVisible"
    :before-close="hideDialog"
    :close-on-click-modal="false"
  >
    <div class="dialogBox">
      <div class="dialog-left">
        <el-divider content-position="left">路段清单</el-divider>
        <div class="dialog-left-table">
          <div class="dialog-left-table-search">
            <el-input
              v-model="formData.roadName"
              placeholder="输入路段名称"
              size="small"
            ></el-input>
            <el-button
              style="margin-left: 20px"
              @click="getTableData()"
              type="primary"
              icon="el-icon-search"
              size="small"
            >
              查询
            </el-button>
            <el-button @click="reset" icon="el-icon-refresh" size="small">
              重置搜索
            </el-button>
            <el-button @click="resetChoose" icon="el-icon-refresh" size="small">
              清空选择
            </el-button>
          </div>
          <el-table
            ref="singleTable"
            style="width: 100%; overflow-y: auto"
            highlight-current-row
            border
            :data="tableData"
            :height="tableDataHeight"
            :header-cell-class-name="getTableClass"
            show-overflow-tooltip
            @row-click="selectBorderData"
            @select="handleSelectionChange"
            @select-all="handleSelectAll"
          >
            <el-table-column type="selection" width="55" />
            <el-table-column
              label="路段名称"
              show-overflow-tooltip
              align="center"
              prop="roadName"
              width="200"
            />
            <el-table-column
              label="路段编号"
              show-overflow-tooltip
              align="center"
              prop="roadCode"
            />
            <el-table-column
              label="路段长度(km)"
              show-overflow-tooltip
              align="center"
              prop="roadLength"
              width="140"
            />
          </el-table>
        </div>
      </div>
      <div class="dialog-right">
        <el-divider content-position="left">已选路段</el-divider>
        <div class="dialog-right-option">
          <el-tag
            v-for="(tag, index) in lineArr"
            :key="tag.id"
            closable
            @close="handleClose(index)"
          >
            <div class="dialog-right-option-tag" :title="tag.roadName">
              {{ tag.roadName }}
            </div>
          </el-tag>
        </div>
      </div>
    </div>

    <div slot="footer" class="dialog-footer" style="text-align: center">
      <el-button @click="cancel">取 消</el-button>
      <el-button type="primary" @click="submitForm">确 定</el-button>
    </div>
  </el-dialog>
</template>

<script>
import { getRoadList } from "@/api/allRequset";
import { deepClone } from "@/utils/deepClone";

export default {
  name: "chooseTableRowYt",
  components: {},
  props: {
    multiple: {
      type: Boolean,
      default: false,
    },
  },
  dicts: ["traffic_device_type"],
  watch: {
    lineArr(val, oldValue) {
      if (val.length === 2 && !this.multiple) {
        this.lineArr = [];
        this.lineArr.push(val[1]);
        this.getTableData();
      }
    },
  },
  data() {
    return {
      title: "",
      dialogVisible: false,
      tableData: [],
      lineArr: [],
      tableDataHeight: 400,
      formData: {},
    };
  },
  methods: {
    hideDialog() {
      this.lineArr = [];
      this.dialogVisible = false;
    },

    handleSelectionChange(row) {
      this.restLineArr(row);
    },

    handleSelectAll(row) {
      this.restLineArr(row);
    },

    restLineArr(row) {
      this.lineArr = [];
      this.lineArr = row.map((item) => {
        return {
          id: item.id,
          roadCode: item.roadCode,
          roadName: item.roadName,
          roadLength: item.roadLength,
          rowData: item,
        };
      });
    },

    showDialog(data) {
      sessionStorage.setItem("lineArr", JSON.stringify(data.data));
      setTimeout(() => {
        let dialogRightOption = document.querySelector(".dialog-right-option");
        let dialogLeftTableSearch = document.querySelector(
          ".dialog-left-table-search"
        );
        this.tableDataHeight =
          dialogRightOption.clientHeight -
          dialogLeftTableSearch.clientHeight -
          40;
      }, 200);
      this.dialogVisible = true;
      this.title = data.title;
      if (data.data) {
        this.lineArr = data.data;
      }
      this.getTableData();
    },

    selectBorderData(row) {
      const index = this.lineArr.findIndex((item) => item.id === row.id);
      if (index === -1) {
        // 如果行不在已选列表中，添加并选中行
        this.lineArr.push({
          id: row.id,
          roadCode: row.roadCode,
          roadName: row.roadName,
          roadLength: row.roadLength,
          rowData: row,
        });
        this.$nextTick(() => {
          this.$refs.singleTable.toggleRowSelection(row, true);
        });
      } else {
        // 如果行已经在列表中，从列表移除并取消选择行
        this.handleClose(index);
      }
    },

    handleClose(index) {
      this.lineArr.splice(index, 1);
      let lineArrCopy = deepClone(this.lineArr);
      this.restLineArr(lineArrCopy);
      this.$refs.singleTable.clearSelection();
      this.lineArr.forEach((item) => {
        let row = this.tableData.find((row) => row.id == item.id);
        this.$nextTick(() => {
          this.$refs.singleTable.toggleRowSelection(row, true);
        });
      });
    },

    submitForm() {
      if (this.lineArr.length > 1 && !this.multiple) {
        this.lineArr = [];
        this.$message.error("只能选择一条路段数据！");
        this.getTableData();
      } else {
        this.$emit("on-response", this.lineArr);
        this.lineArr = [];
        this.hideDialog();
      }
    },

    cancel() {
      this.lineArr = [];
      let arr = JSON.parse(sessionStorage.getItem("lineArr"));
      this.$emit("on-response", arr);
      sessionStorage.removeItem("lineArr");
      this.hideDialog();
    },

    getTableData() {
      getRoadList({
        roadName: this.formData.roadName,
      })
        .then((res) => {
          if (res.data.code === 1) {
            this.tableData = res.data.data;
          }
        })
        .finally(() => {
          if (this.lineArr) {
            this.lineArr.forEach((row) => {
              this.$nextTick(() => {
                let matchedRow = this.tableData.find((e) => e.id === row.id);
                if (matchedRow) {
                  this.$refs.singleTable.toggleRowSelection(matchedRow, true);
                }
              });
            });
          } else {
            this.$refs.singleTable.clearSelection();
          }
        });
    },

    reset() {
      this.$set(this.formData, "roadName", null);
      this.getTableData();
    },

    resetChoose() {
      this.$nextTick(() => {
        this.$refs.singleTable.clearSelection();
      });
      this.lineArr = [];
    },

    getTableClass({ row, column, rowIndex, columnIndex }) {
      if (columnIndex === 0 && !this.multiple) {
        return "hideChooseAll";
      }
    },
  },
  created() {},
  mounted() {},
};
</script>

