<template>
  <div>
    <backHomeBtn>
      <template>
        <el-input v-model="basicForm.roadNames" placeholder="" disabled>
          <template slot="append">
            <div class="choose-class" @click="chooseRoadSection">
              <i class="iconfont if-sousuo" /> <span>选择</span>
            </div>
          </template>
        </el-input>

        <!--        {{ lineArr }}-->
      </template>
    </backHomeBtn>

    <chooseTableRowYt
      ref="chooseTableRowYt"
      multiple
      @on-response="getRoadSection"
    />
  </div>
</template>

<script>
import chooseTableRowYt from "@/components/chooseTableRowYt/chooseTableRowYt.vue";

export default {
  name: "tableAndTag",
  components: { chooseTableRowYt },
  props: {},
  data() {
    return {
      lineArr: [],
      basicForm: {},
    };
  },
  methods: {
    chooseRoadSection() {
      let passData = {
        data: this.lineArr,
        title: "选择关联路段",
      };
      this.$refs.chooseTableRowYt.showDialog(passData);
    },

    getRoadSection(data) {
      this.lineArr = data;
      if (data !== []) {
        let arr = data.map((item) => item.roadName);
        this.$set(this.basicForm, "roadNames", arr.join(","));
      } else {
        this.$set(this.basicForm, "roadNames", "");
      }
    },
  },
  created() {},
  mounted() {},
};
</script>

<style lang="scss" scoped>
.choose-class {
  cursor: pointer;
  color: #409eff;
  font-weight: bold;
}
</style>
